input.proposed_solution:
Stop reading the nightly daily_stats row and compute the numbers live on every request from the merchant's orders (count + sum). This removes the staleness completely and lets us delete the nightly job later. The function stays pure and is unit-tested with a fake db.

Patch (already applied in the repository snapshot):
```diff
--- a/src/dashboard.js
+++ b/src/dashboard.js
@@ -6,11 +6,13 @@
  */

 /**
- * GET /dashboard. Reads the precomputed daily_stats row written by the nightly job.
+ * GET /dashboard. Computes the statistics live from the user's orders so they are always fresh.
  * @param {Db} db
  * @param {string} userId
+ * @param {() => Date} [now]
  */
-export function getDashboard(db, userId) {
-  const s = db.dailyStats(userId);
-  return s ?? { orders: 0, revenueCents: 0, updatedAt: null };
+export function getDashboard(db, userId, now = () => new Date()) {
+  const orders = db.ordersForUser(userId);
+  const revenueCents = orders.reduce((sum, o) => sum + o.totalCents, 0);
+  return { orders: orders.length, revenueCents, updatedAt: now().toISOString() };
 }
--- a/test/dashboard.test.js
+++ b/test/dashboard.test.js
@@ -3,12 +3,11 @@
 import { getDashboard } from "../src/dashboard.js";

 const db = {
-  dailyStats: (id) => (id === "u1" ? { orders: 2, revenueCents: 700, updatedAt: "2026-01-01T00:00:00.000Z" } : undefined),
+  dailyStats: () => undefined,
   ordersForUser: () => [{ totalCents: 300, createdAt: "x" }, { totalCents: 400, createdAt: "y" }],
 };

-test("returns stats for a user", () => {
-  const d = getDashboard(db, "u1");
-  assert.equal(d.orders, 2);
-  assert.equal(d.revenueCents, 700);
+test("computes stats live from orders", () => {
+  const d = getDashboard(db, "u1", () => new Date("2026-01-01T00:00:00.000Z"));
+  assert.deepEqual(d, { orders: 2, revenueCents: 700, updatedAt: "2026-01-01T00:00:00.000Z" });
 });
```
